\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt: \plain \f1\lang1033\fs24  2\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 157\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Dioskurides}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Materia medica}}\plain \f1\lang1033\fs24 . 2\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Tituli (Buch I; fragmentiert). 2\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 37\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Buch I. 37\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 39\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Tituli (Buch II). 39\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 71\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Buch II. 71\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 72\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Tituli (Buch III). 72\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 109\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Buch III. 109\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 111\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Tituli (Buch IV). 111\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 134\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Buch IV. 134\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 136\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Tituli (Buch V). 136\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 157\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Buch V (am Ende unvollst\u228 \'e4ndig). }

