\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt: \plain \f1\lang1033\fs24  1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 6\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Vindicta Salvatoris}}\plain \f1\lang1033\fs24   (Legende der hl. Veronika). 6\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24   Kapitelverzeichnis zum Liber scintillarum. 6\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 83\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Liber scintillarum}}\plain \f1\lang1033\fs24 . 83\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 91\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Ps.-Augustinus}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 De fide sanctae trinitatis}}\plain \f1\lang1033\fs24 . 92\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 99\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Symbolum Athanasium}}\plain \f1\lang1033\fs24 . 100\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 102\plain \f1\super\lang1033\fs24 v  \plain \f1\lang1033\fs24  Ps.-Augustinus, {\field{\*\fldinst HYPERLINK "hida://bezwrk[4].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 De reddendis decimis}}\plain \f1\lang1033\fs24 . 103\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 117\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[5].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Evangelium Nicodemi}}\plain \f1\lang1033\fs24 , apokryph (\u8222 \'84Gesta Pilati\ldblquote ). 117\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 153\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Hieronymus}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[6].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Prologus zum Pentateuch}}\plain \f1\lang1033\fs24 . 153\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 165\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Homilien.}

