\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt: \plain \f1\lang1033\fs24  I\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash II\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Casus poenitentiales (15. Jh.). III\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\scaps\lang1033\fs24  \plain \f1\lang1033\fs24  Kapitel\u252 \'fcbersicht der nachfolgenden Sententiae (vom selben Schreiber, auf zusammengest\u252 \'fccktem Blatt). 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 68\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Hugo de Sancto Victore}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Sententiae}}\plain \f1\lang1033\fs24 . 68\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 69\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Anonym, {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 De coniugio}}\plain \f1\lang1033\fs24 . 70\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 79\plain \f1\super\lang1033\fs24 r {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Petrus Pictaviensis de Sancto Victore}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Liber poenitentialis}}\plain \f1\lang1033\fs24 . 79\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 80\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Miracula Mariae (Exzerpte verschiedener Autoren). 81\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 94\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Anonym, {\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Tractatus de divini verbi incarnatione}}\plain \f1\lang1033\fs24   (ab 92\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   kurze erg\u228 \'e4nzende Verse). 95\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 141\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Honorius Augustodunensis}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[4].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Gemma animae de divinis officiis}}\plain \f1\lang1033\fs24 . 141\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 142\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Gebetstexte. 142\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[3].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Galfredus Babio}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[5].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 In Matthaeum}}\plain \f1\lang1033\fs24   (Exzerpt).}

