\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Ausstattung: \plain \f1\lang1033\fs24  8 rote {\field{\*\fldinst HYPERLINK "hida://5240[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Silhouetteninitialen}}\plain \f1\lang1033\fs24 , teils im gespaltenen Stamm oder Binnenraum blaues oder gr\u252 \'fcnes Farbband. Drei 5\endash 9-zeilige Rankeninitialen (H\u246 \'f6he: 5\endash 8,5 cm) in roter Federzeichnung und Deckfarben: schlichter Buchstabenk\u246 \'f6rper in Farbe bzw. bestehend aus wei\u223 \'df ausgesparten, dicht ineinander verschlungenen R\u246 \'f6hrenranken mit seitlich angesetzten Knollenbl\u228 \'e4ttern und vereinzelten Blattmanschetten, vielfach endend in Halbpalmetten, Palmetten, hochgew\u246 \'f6lbten Schirmbl\u228 \'e4ttern oder einseitig gelappten T\u252 \'fctenbl\u228 \'e4ttern mit geradlinigen Konturen (rot geadert durch Doppellinien oder feine Querstrichelung, teils farbig angelegt) vor gr\u252 \'fcn und blau parzelliertem Initialgrund bzw. Binnenraum. }

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset238 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

