\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt: \plain \f1\lang1033\fs24  1\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24   Inhalts\u252 \'fcbersicht (von {\field{\*\fldinst HYPERLINK "hida://bezper[6].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Hartmann Schedel}}\plain \f1\lang1033\fs24 ). 2\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 9\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Anonyme {\field{\*\fldinst HYPERLINK "hida://bezwrk[7].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Timaios-Compilatio (Ad philosophiam et astrologiam)}}\plain \f1\lang1033\fs24 . 11\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 37\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Boethius}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Commentarium super Perihermenias Aristotelis}}\plain \f1\lang1033\fs24   (am Ende unvollst\u228 \'e4ndig). 38\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 39\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Adalbero Laudunensis}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Epistola ad Fulconem Ambianum episcopum}}\plain \f1\lang1033\fs24 . 39\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24   In divina scriptura quadruplex habitatio intellectus (? Exzerpt aus {\field{\*\fldinst HYPERLINK "hida://bezper[3].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Stephanus Langton}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 In XII prophetas}}\plain \f1