\pard\sl256\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 {\field{\*\fldinst HYPERLINK "hida://5240[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Fleuronn\u233 \'e9e-Initialen}}\plain \f1\lang1033\fs24  (und Paragraphzeichen)\plain \f1\scaps\lang1033\fs24 : \plain \f1\lang1033\fs24  2\endash 4-zeilige rote Lombarden (H\u246 \'f6he: 2\endash 3 cm) mit braunem Fleuronn\u233 \'e9e. Besatz und Binnenraum: Konturbegleitstriche, die durch kurze Querstege mit Buchstabenstamm verbunden sind und sich zu Halbpalmetten mit Kern und meistens mit verl\u228 \'e4ngerten Fadenranken erweitern (Paragraphzeichen: gelegentlich vergleichbares Fleuronn\u233 \'e9e in Rot). Vereinzelt braune Fleuronn\u233 \'e9eleiste neben Schriftspiegel: Parallelf\u228 \'e4den mit einseitigem Besatz von Perlenreihen mit Kern und Halbpalmetten (z.B. 15\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   und 16\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ). 21\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   in Tinte gezeichneter M\u228 \'e4nnerkopf im Profil. 92\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Binnenraum durch Quersteg unterteilt, den nach oben und unten rechtwinklig abstehende Parallelf\u228 \'e4den s\u228 \'e4umen. }

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

