\pard\sl256\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 {\field{\*\fldinst HYPERLINK "hida://5240[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Silhouetten-Initialen}}\plain \f1\lang1033\fs24  und ornamentaler Wind\plain \f1\scaps\lang1033\fs24 : \plain \f1\lang1033\fs24  2\endash 5-zeilige Lombarden (H\u246 \'f6he: 1\endash 3 cm), alternierend in roter und blauer Tinte, mit sp\u228 \'e4rlichem konturbegleitenden Palmettenfleuronn\u233 \'e9e in der Gegenfarbe (z.B. 32\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ). 155\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   zweifarbig ornamental gespaltener Stamm, Fleuronn\u233 \'e9ebesatz erweitert um Fadenranke mit seitlich umgebogenen Trichterbl\u252 \'fcten mit doppelt gefasstem oberen Abschluss und dichtem Wimpernbesatz. Vereinzelt auch \endash  anstelle der Initiale \endash  das vorgeschaltete Paragraphzeichen verziert, z.B. mit umblickendem Tierkopf in gekurvtem Ausl\u228 \'e4ufer (z.B. 33\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ). Bl. 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   ornamentaler Wind: gefl\u252 \'fcgelter Drache, mit verdrehtem Kopf in den Fu\u223 \'df des Initialschafts verbissen und unterhalb des Schriftspiegels in einen flachen Tiersch\u228 \'e4del \u252 \'fcbergeleitet, dessen gez\u228 \'e4hntem Maul horizontal geb\u252 \'fcndelte Strahlen entspringen, die \endash  teils durch pustende kleine Kugelk\u246 \'f6pfe geleitet \endash  in Fr\u252 \'fcchten, Zapfen aus Voluten und Schwertspitzen enden.  }

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

