\pard\sl256\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 {\field{\*\fldinst HYPERLINK "hida://5240[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Randzeichnungen}}\plain \f1\scaps\lang1033\fs24  \plain \f1\lang1033\fs24  (unterer Blattrand, blaue und rote Tinte)\plain \f1\scaps\lang1033\fs24 : \plain \f1\lang1033\fs24  1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   nach rechts schreitender {\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 L\u246 \'f6we}}\plain \f1\lang1033\fs24   im Profil. 3\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   zwei gegenst\u228 \'e4ndige gefl\u252 \'fcgelte {\field{\*\fldinst HYPERLINK "hida://5500[1]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Drachen}}\plain \f1\lang1033\fs24   mit nach unten geneigten, korkenzieherartig verwundenen H\u228 \'e4lsen, die sich jeweils in den eigenen Leib verbei\u223 \'dfen, \u252 \'fcber zentralem Rankenast aus Elementen ornamentaler Winde (dicht ineinandergesteckte Trichterbl\u228 \'e4tter [Fischgr\u228 \'e4tenmuster] mit seitlich angesetzten Profilbl\u228 \'e4ttern, konische Leiste aus Halbkringeln und Perlen, kurze Rankenf\u228 \'e4den und Voluten). }

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;\red157\green185\blue235;}

