\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt: \plain \f1\lang1033\fs24  1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 97\plain \f1\super\lang1033\fs24 v\plain \f2\lang1033\fs20\cf1  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18\cf1 Bernardus Papiensis}}\plain \f1\lang1033\fs24\cf1 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Breviarium extravagantium decretalium}}\plain \f1\lang1033\fs24\cf1  mit Glossen (5 B\u252 \'fccher).\plain \f1\lang1033\fs24   98\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24   vacant. 99\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 149\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Compilatio decretalium}}\plain \f1\lang1033\fs24 . 149\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacat. 150\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 266\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Innocentius III.}}\plain \f1\lang1033\fs24 , Papa, {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Decretales}}\plain \f1\lang1033\fs24 . 267\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 304\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Idem, {\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 De summa trinitate}}\plain \f1\lang1033\fs24 . 304\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 305\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacant.  }

