\pard\sl254\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 {\field{\*\fldinst HYPERLINK "hida://5240[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Fleuronne\u769 ?est\u228 \'e4be}}\plain \f1\lang1033\fs24  bzw. ornamentale Winde\plain \f1\scaps\lang1033\fs24 : \plain \f1\lang1033\fs24  Gezeichnete Fleuronn\u233 \'e9est\u228 \'e4be (19\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 49\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 72\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 77\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 88\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) bzw. ornamentale Winde mit {\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Drachen}}\plain \f1\lang1033\fs24   oder Mischwesen (1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 8\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 37\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 62\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 64\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 77\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 80\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 150\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   [menschlicher Kopf], 182\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   [Vogelkopf], 209\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 239\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   [geschn\u228 \'e4belt, ohne Fleuronn\u233 \'e9e], 245\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   [menschlicher Kopf]) in roter und blauer Tinte: Mittellinie oder zentrale Zierleiste (ineinandergesteckte Trichterbl\u228 \'e4tter [Fischgr\u228 \'e4tenmuster] mit seitlichen Voluten oder Halbpalmetten, kolbenartig formierte Doppelvoluten bzw. Halbkringel, Perlen, Einzelrosetten) mit beidseitigem, meist axialsymmetrischem Besatz: schr\u228 \'e4g abstehende oder parallel gef\u252 \'fchrte Einzelf\u228 \'e4den mit Endvoluten oder Punktverdickung, Staubf\u228 \'e4den. }

