\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt: \plain \f1\lang1033\fs24  1\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Tabula zur Berechnung des Ostertags. 2\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 29\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Summa de articulis fidei et de VII sacramentis ecclesie. 30\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Sentenzen (Exzerpte). 30\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 50\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Hymnus \plain \f1\i\lang1033\fs24  Ut queant laxis \plain \f1\lang1033\fs24  (mit Kommentar). 50\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24   Nachtr\u228 \'e4ge von verschiedenen H\u228 \'e4nden. 51\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 59\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Liber lapidarius}}\plain \f1\lang1033\fs24   (letzte Seite mehrfach durchgestrichen). 60\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 61\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Nachtrag in deutscher Sprache. 62\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 78a\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Henricus Septimellensis}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Elegia de diversitate fortunae}}\plain \f1\lang1033\fs24 . 78b\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Nachtrag. 78b\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacat. 79\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 93\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Sedulius Caelius}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Paschale Carmen}}\plain \f1\lang1033\fs24 . 93\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 95\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Wunder des Otto Bambergensis}}\plain \f1\lang1033\fs24 . 96\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 100\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[4].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 De arithmetica}}\plain \f1\lang1033\fs24 . 101\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Fragment eines philosophischen Traktats. 101\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 104\plain \f1\super\lang1033\fs24 v {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Alexander de Villa Dei}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[5].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Algorismus metricus}}\plain \f1\lang1033\fs24 .}

