\pard\sl256\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 {\field{\*\fldinst HYPERLINK "hida://5240[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Fleuronn\u233 \'e9e-Initialen}}\plain \f1\scaps\lang1033\fs24 : \plain \f1\lang1033\fs24  51\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   kleine rote Lombarde mit konturparallelem Fadenbesatz in blauer Tinte (3-zeilig; Init.-H\u246 \'f6he: 1 cm) sowie gro\u223 \'dfe Fleuronn\u233 \'e9e-Initiale (blauer Stamm ornamental gespalten; Besatz und Binnenraum mit dichtem Palmettenfleuronn\u233 \'e9e in roter Tinte: einzelne, verzweigte oder zu B\u252 \'fcscheln vereinte gestielte Halbpalmetten mit blauem Kern, kombiniert mit Fr\u252 \'fcchten und Voluten (10-zeilig, Init.-H\u246 \'f6he: 4 cm).}

