\pard\sl256\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 \plain \f1\lang1033\fs24 Autonome {\field{\*\fldinst HYPERLINK "hida://5240[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Randzeichnungen}}\plain \f1\scaps\lang1033\fs24 : \plain \f1\lang1033\fs24  1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   querst\u228 \'e4ndiger Profilkopf, dessen Mund nach oben das Fleuronn\u233 \'e9e der Anfangsinitiale zu entspringen scheint. 14\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   am unteren Seitenrand Halbfigur eines Mannes im Profil nach rechts, dicht vor seinen Lippen Blattranken. 38\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   am unteren Blattrand Halbfigur eines {\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Wolfshundes}}\plain \f1\lang1033\fs24   mit heraush\u228 \'e4ngender Zunge.}

