\pard\sl256\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 {\field{\*\fldinst HYPERLINK "hida://5240[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Fleuronn\u233 \'e9e-Initialen}}\plain \f1\lang1033\fs24  und \endash st\u228 \'e4be: Aus Text herausgezogen 1\endash 13-zeilige rote oder blaue Lombarden (H\u246 \'f6he: 0,5\endash 5 cm) mit sp\u228 \'e4rlichem Fleuronn\u233 \'e9e in der Gegenfarbe (Besatz und Binnenraum: Konturbegleitf\u228 \'e4den mit palmettenartigen Ausbuchtungen und/oder unterbrochen von Staubf\u228 \'e4den; verl\u228 \'e4ngerte Cauda gelegentlich mit Punktverdickung, einseitig angesetzten Wimpern oder Profilbl\u228 \'e4ttern). Den Schriftspiegel vertikal flankierende Fleuronn\u233 \'e9e-St\u228 \'e4be: vor allem intermittierende Palmettenranken (auch in Teilst\u252 \'fccken) mit runden Blattlappen (h\u228 \'e4ufig jeweils mit Binnenpunkt) und/oder dicht schraffierter Aderung, teils mit Zwickelfr\u252 \'fcchten und schr\u228 \'e4g abstehendem Leitermotiv (z.B. 58\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 75\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ). }

