\uc1
\pard\sl256\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 {\field{\*\fldinst HYPERLINK "hida://5240[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Drolerien}}\plain \f1\lang1033\fs24  und ornamentale Winde\plain \f1\scaps\lang1033\fs24 : \plain \f1\lang1033\fs24  Meist am Fu\u223 \'df der Seite stilisierte V\u246 \'f6gel (z.B. 153\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 177\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ), Papageien (z.B. 11\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ), Drachen (z.B. 121\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ), Vierbeiner (oft mit ausgepr\u228 \'e4gten H\u246 \'f6rnern oder Geweih; z.B. 81\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 97\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 200\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) und Mischwesen (teils mit menschlichem Kopf; z.B. 105\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 113\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 129\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 137\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) in roter, blauer oder gr\u252 \'fcner Federzeichnung, ganz oder partiell mit Deckfarben koloriert (\u252 \'fcberwiegend rote Zeichnung mit gr\u252 \'fcner Deckfarbe). Bl. 3\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 7\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 7\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 14\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 47\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 90\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 119\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 151\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 176\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   u. 195\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   jeweils Drolerien oder K\u246 \'f6pfe, aus deren M\u228 \'e4ulern vertikal ornamentale Winde (wie Fleuronn\u233 \'e9est\u228 \'e4be) hervorgehen. Farben: Mittelblau, Gr\u252 \'fcn, Hellrot, Dunkelrot, Ocker, Gelb. }

