\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt: \plain \f1\lang1033\fs24  1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 134\plain \f1\super\lang1033\fs24 r\plain \f1\b\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Thomas de Aquino}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Commentum super duodecim libris metaphysicae}}\plain \f1\lang1033\fs24   (1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 17\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Buch 1; 17\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 20\plain \f1\super\lang1033\fs24 r\plain \f1\b\lang1033\fs24   \plain \f1\lang1033\fs24  Buch 2; 20\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 29\plain \f1\super\lang1033\fs24 v\plain \f1\b\lang1033\fs24   \plain \f1\lang1033\fs24  Buch 3;\plain \f1\b\lang1033\fs24   \plain \f1\lang1033\fs24  30\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 41\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Buch 4; 41\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 59\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Buch 5; 59\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 64\plain \f1\super\lang1033\fs24 v\plain \f1\b\lang1033\fs24   \plain \f1\lang1033\fs24  Buch 6;\plain \f1\b\lang1033\fs24   \plain \f1\lang1033\fs24  64\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 87\plain \f1\super\lang1033\fs24 r\plain \f1\b\lang1033\fs24   \plain \f1\lang1033\fs24  Buch 7; 87\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 92\plain \f1\super\lang1033\fs24 r\plain \f1\b\lang1033\fs24   \plain \f1\lang1033\fs24  Buch 8; 92\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 100\plain \f1\super\lang1033\fs24 r\plain \f1\b\lang1033\fs24   \plain \f1\lang1033\fs24  Buch 9; 100\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 110\plain \f1\super\lang1033\fs24 v\plain \f1\b\lang1033\fs24   \plain \f1\lang1033\fs24  Buch 10; 110\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 122\plain \f1\super\lang1033\fs24 v\plain \f1\b\lang1033\fs24   \plain \f1\lang1033\fs24  Buch 11; 122\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 134\plain \f1\super\lang1033\fs24 r\plain \f1\b\lang1033\fs24   \plain \f1\lang1033\fs24  Buch 12). 134\plain \f1\super\lang1033\fs24 r\plain \f1\b\lang1033\fs24  \endash \plain \f1\lang1033\fs24  140\plain \f1\super\lang1033\fs24 v\plain \f1\b\lang1033\fs24   \plain \f1\lang1033\fs24  Anonym, {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Supplementum super librum XIII metaphysicae}}\plain \f1\lang1033\fs24   (Ende fehlt). Siehe \plain \f1\scaps\lang1033\fs24 Dondaine / Shooner.}

