\pard\sl256\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 {\field{\*\fldinst HYPERLINK "hida://5240[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Fleuronn\u233 \'e9e-Initialen}}\plain \f1\scaps\lang1033\fs24 : \plain \f1\lang1033\fs24  2\endash 3-zeilige rote und blaue Lombarden (aus Textspiegel herausger\u252 \'fcckt), h\u228 \'e4ufig im Senkrechtschaft nach unten verl\u228 \'e4ngert, mit schlichtem Fleuronn\u233 \'e9e in der Gegenfarbe. Besatz: Parallelf\u228 \'e4den mit leicht eingerollten Ausl\u228 \'e4ufern, z.T. Halbpalmetten bildend und in Haarnadelkurven endend. Binnenraum: Konturbegleitstriche bzw. Fadenspiralranken. Ausnahme 243\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 : 4-zeilige Initiale mit ornamental zweifarbig gespaltenem Stamm.}

