\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  242\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Arzt}}\plain \f1\lang1033\fs24   am Krankenbett, in F(\plain \f1\i\lang1033\fs24  ebris est calor extraneus\plain \f1\lang1033\fs24 ). Init.-H\u246 \'f6he: 20,5 cm. Der wei\u223 \'df gekleidete {\field{\*\fldinst HYPERLINK "hida://5500[1]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Fieberkranke}}\plain \f1\lang1033\fs24   sitzt in seinem Bett, w\u228 \'e4hrend der von hinten kommende Arzt in rotem Umhang seine linke Hand ergreift. Die Szene \endash  durch blauen Grund mit wei\u223 \'dfen Spiralranken hinterfangen und von architektonischen Elementen (Mauerwerk, Zinnen, Zentralkuppel) \u252 \'fcberh\u246 \'f6ht \endash  wird von den beiden Querbalken des F gerahmt. Initialstamm aus blauen und rosafarbenen Ranken mit breiten, f\u228 \'e4cherartig wei\u223 \'df geaderten Profil- und T\u252 \'fctenbl\u228 \'e4ttern, teils unterbrochen von Goldpollen bzw. kleinen Farbovalen mit vegetabiler Binnenstruktur, vor schwarz konturiertem Feld (gebogt und gebuchtet) in Blattgold; unterer Ausl\u228 \'e4ufer in symmetrische Bl\u252 \'fctenformation mit Lanzettbl\u228 \'e4ttern endend.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Verdana;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red157\green185\blue235;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  312\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Apotheker}}\plain \f1\lang1033\fs24   bei der Arbeit, in P(\plain \f1\i\lang1033\fs24  ostquam expediti sumus\plain \f1\lang1033\fs24 ). Grau gekleideter Apotheker mit wei\u223 \'dfer Haube sitzt im Dreiviertelprofil auf Bank, einen gro\u223 \'dfen goldenen M\u246 \'f6rser zwischen den Beinen, und r\u252 \'fchrt mit einem langen Stiel im Gef\u228 \'e4\u223 \'df, w\u228 \'e4hrend er mit dem St\u246 \'f6\u223 \'dfel in der anderen Hand weit ausholt; das Innere seiner Apotheke wird rechts durch vier Regalbretter mit verschiedenen Gef\u228 \'e4\u223 \'dfen spezifiziert; hinterfangen von ultramarinblauem Grund mit wei\u223 \'dfen Spiralranken; getrepptes und gebuchtetes Initialfeld in Blattgold. Ausl\u228 \'e4ufer der Initiale (Gestaltung wie 242\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) in symmetrische Kombination aus Ranken, Profil-, Kelch- und T\u252 \'fctenbl\u228 \'e4ttern, Pollen und Tropfen in Gold m\u252 \'fcndend\plain \f1\scaps\lang1033\fs24 .}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset186 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red157\green185\blue235;\red204\green238\blue221;}

