\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt: \plain \f1\lang1033\fs24  I\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   verschiedene sp\u228 \'e4tere Notizen. 1\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24   Rubrikenverzeichnis zu den Decretales. 2\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 126\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Godefridus de Trano}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Summa super titulis decretalium}}\plain \f1\lang1033\fs24   (2\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 37\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Buch I; 37\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 62\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Buch II; 62\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 86\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Buch III; 86\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 98\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Buch IV; 98\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 126\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Buch V). 126\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 132\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   verschiedene Konstitutionen und Exzerpte (z.B. Formularsammlung zur Gesetzgebung Friedrichs II.). 133\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   vacat. 133\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Exzerpte und Rubrikenverzeichnis zum Liber Augustalis. 134\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 142\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldins