\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt: \plain \f1\lang1033\fs24  I\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24   Eintragungen des 15. Jhs. 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 427\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Iustinianus}}\plain \f1\lang1033\fs24   imperator, {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Codex}}\plain \f1\lang1033\fs24   (9 B\u252 \'fccher) mit Glossen, u.a. des {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Accursius}}\plain \f1\lang1033\fs24   (1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 62\plain \f1\super\lang1033\fs24 v \plain \f1\lang1033\fs24  Buch 1; 63\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 114\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Buch 2; 115\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 150\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Buch 3; 150\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 208\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Buch 4; 209\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 266\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Buch 5; 266\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 328\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Buch 6; 328\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 374\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Buch 7; 375\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 408\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Buch 8 [Ende fehlt]; 409\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 427\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Buch 9 [Anfang fehlt]). 427\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacat. 428\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Rubrikenverzeichnis. 428\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Juristische Noten (Glossenschrift). 429\plain \f1\super\lang1033\fs24 r \plain \f1\lang1033\fs24  Rubrikenverzeichnis. Siehe \plain \f1\scaps\lang1033\fs24 Rauner 2007.}

