\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt: \plain \f1\lang1033\fs24  1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 12\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Johannes Alexandrinus}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Isagoge ad Artem parvam Galeni}}\plain \f1\lang1033\fs24 . 12\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 48\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Galenus}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Ars parva}}\plain \f1\lang1033\fs24 . 49\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 121\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Hippocrates latinus. 122\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24   medizinische Nachtr\u228 \'e4ge. 123\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 152\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Avicenna}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Canon medicinae}}\plain \f1\lang1033\fs24 , Buch IV. 153\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 174\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Idem, {\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Chirurgia}}\plain \f1\lang1033\fs24 . 174\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 195\plain \f1\super\lang1033\fs24