\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt: \plain \f1\lang1033\fs24  I\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   vacat (mit Eintrag, s.o.). I\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash II\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Johannes de Deo}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Commentum arboris de consanguinitate et affinitate}}\plain \f1\lang1033\fs24 . II\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash III\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacant. 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 261\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Gregorius IX.}}\plain \f1\lang1033\fs24 ,  Papa, {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Liber extra}}\plain \f1\lang1033\fs24   mit diversen Glossen (u.a. des {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Bernardus Bottonius}}\plain \f1\lang1033\fs24 ). 262\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   vacat. 262\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 263\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[3].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Johannes Andreae}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Lectura super arboribus consanguinitatis et affinitatis}}\plain \f1\lang1033\fs24 . 263\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Rubriken zum Liber extra.}

