\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  1a\plain \f1\super\lang1033\fs24 r {\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Rechtsstreit}}\plain \f1\lang1033\fs24   um die eheliche Mitgift (Buch XXIV). 9 x 7 cm. Vor dreiteiliger Architektur thront zentral der weltliche {\field{\*\fldinst HYPERLINK "hida://5500[2]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Richter}}\plain \f1\lang1033\fs24   mit Buch, w\u228 \'e4hrend links die {\field{\*\fldinst HYPERLINK "hida://5500[1]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Ehefrau}}\plain \f1\lang1033\fs24   mit Klageschrift und rechts der Ehemann \endash  jeweils mit ihrer Gefolgschaft \endash  stehen; die von T\u252 \'fcrmen \u252 \'fcberh\u246 \'f6hte Kulisse ragt \u252 \'fcber die Kapitel\u252 \'fcberschrift hinaus und tr\u228 \'e4gt einen drapierten Vorhang. }

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Verdana;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red157\green185\blue235;\red157\green185\blue235;}

