\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  9\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Verwendungen auf die Mitgift (Buch XXV). 5,5 x 7 cm. Im schmaleren linken Teil stehen vor Goldgrund die vornehm gekleidete {\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Ehefrau}}\plain \f1\lang1033\fs24   und ein {\field{\*\fldinst HYPERLINK "hida://5500[1]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Jurist}}\plain \f1\lang1033\fs24   und informieren sich \u252 \'fcber die vom Ehemann geltend gemachten Abz\u252 \'fcge f\u252 \'fcr die notwendige und nutzbringende Erhaltung und Bearbeitung des Dotalgrundst\u252 \'fccks; im rechten Bildfeld sind flei\u223 \'dfige {\field{\*\fldinst HYPERLINK "hida://5500[2]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Landarbeiter}}\plain \f1\lang1033\fs24   mit dem Ackern, Baumschnitt und der Pflege von Weinreben besch\u228 \'e4ftigt.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Verdana;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red157\green185\blue235;\red157\green185\blue235;}

