\pard\sl256\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 {\field{\*\fldinst HYPERLINK "hida://5240[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Fleuronn\u233 \'e9e-Initialen}}\plain \f1\scaps\lang1033\fs24 : \plain \f1\lang1033\fs24  2\endash 4-zeilige (nach kleinerem Schriftgrad) rote und blaue Lombarden im Wechsel, mit Fleuronn\u233 \'e9e in der Gegenfarbe (Init.-H\u246 \'f6he: 1\endash 1,5 cm). Besatz und Binnenraum: vertikale Parallelf\u228 \'e4den mit perlenartigen oder mehrfach gebogten Ausbuchtungen bzw. seitlich anhaftenden Perlen, als Ausl\u228 \'e4ufer verl\u228 \'e4ngerte Einzelf\u228 \'e4den mit gekurvtem Ende. Ausnahme 47\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 : drei 2-zeilige Initialen mit sehr feinem Fleuronn\u233 \'e9e (blockartig erweiterte Initialfelder; Besatz und Binnenraum: dichte Spiralfadenranken; Perlenst\u228 \'e4be, Knospenfleuronn\u233 \'e9e).}

