\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  166\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Zust\u228 \'e4ndigkeit von weltlicher oder kirchlicher Rechtsprechung (\plain \f1\i\lang1033\fs24  Causa XI\plain \f1\lang1033\fs24 ). 8,5 x 9 cm. Links und rechts thronen jeweils ein {\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Bischof}}\plain \f1\lang1033\fs24   bzw. ein weltlicher Rechtsgelehrter vor architektonischen Aufbauten, w\u228 \'e4hrend sich von der Mitte der {\field{\*\fldinst HYPERLINK "hida://5500[1]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Szene}}\plain \f1\lang1033\fs24   aus Kleriker bzw. Laien an den f\u252 \'fcr sie zust\u228 \'e4ndigen {\field{\*\fldinst HYPERLINK "hida://5500[2]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Richter}}\plain \f1\lang1033\fs24   wenden.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Verdana;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red157\green185\blue235;\red157\green185\blue235;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  179\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Eigenm\u228 \'e4chtiges Verf\u252 \'fcgen von Klerikern \u252 \'fcber pers\u246 \'f6nlichen und kirchlichen Besitz (\plain \f1\i\lang1033\fs24  Causa XII\plain \f1\lang1033\fs24 ). 8,5 x 9,5 cm. Zweigeteilte Szene mit Simultandarstellung: rechts der bequem gelagerte, sterbende Geistliche, der sein {\field{\*\fldinst HYPERLINK "hida://5500[1]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Testament}}\plain \f1\lang1033\fs24   verfasst hat; links konsultieren Angeh\u246 \'f6rige seiner Gemeinschaft mit dem Testament in der Hand den {\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Bischof}}\plain \f1\lang1033\fs24   und den Erzbischof zur Rechtslage. }

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Verdana;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red157\green185\blue235;\red157\green185\blue235;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  190\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Pflichten gegen\u252 \'fcber der eigenen Taufgemeinde, selbst nach Wohnortwechsel (\plain \f1\i\lang1033\fs24  Causa XIII\plain \f1\lang1033\fs24 ). 8,5 x 8,5 cm. In der zweigeteilten Darstellung stehen links zwei bewaffnete Soldaten vor einem Geb\u228 \'e4ude, eine {\field{\*\fldinst HYPERLINK "hida://5500[1]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Frau}}\plain \f1\lang1033\fs24   mit einem Wickelkind deutet auf sie: bildhafte Umsetzung von Gratians Fragestellung, ob Menschen, die ihre Heimatgemeinde wegen kriegerischer Bedrohung verlassen haben, aber weiterhin ihre dortigen Felder bewirtschaften, die Steuern an ihrem neuen Wohnort entrichten d\u252 \'fcrfen. Dementsprechend ist rechts die {\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 \u220 \'dcbergabe}}\plain \f1\lang1033\fs24   des Zinses (in Form eines Gelds\u228 \'e4ckchens) zu sehen.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Verdana;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red157\green185\blue235;\red157\green185\blue235;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  195\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Wucher treibende Kanoniker (\plain \f1\i\lang1033\fs24  Causa XIV\plain \f1\lang1033\fs24 ). 8,5 x 8 cm. Architektonisch gegliederte dreiteilige {\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Szene}}\plain \f1\lang1033\fs24 . Der links thronende Bischof diszipliniert die in der Mitte und rechts stehenden M\u246 \'f6nche, nachdem diese mit ihrem Geld spekuliert hatten.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Verdana;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red157\green185\blue235;\red157\green185\blue235;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  198\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Urteile gegen Geistliche wegen unmoralischer und krimineller Vergehen (\plain \f1\i\lang1033\fs24  Causa XV\plain \f1\lang1033\fs24 ). 9 x 9 cm. {\field{\*\fldinst HYPERLINK "hida://5500[1]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Szene}}\plain \f1\lang1033\fs24   unter drei abgeflachten Arkadenb\u246 \'f6gen. Der Beklagte \endash  hier jeweils rosa gekleidet \endash  wird von rechts nach links in drei unterschiedlichen Momenten dargestellt: einmal bei seiner fleischlichen S\u252 \'fcnde (eine Frau {\field{\*\fldinst HYPERLINK "hida://5500[2]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 umarmend}}\plain \f1\lang1033\fs24 ), dann beim {\field{\*\fldinst HYPERLINK "hida://5500[3]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Erschlagen}}\plain \f1\lang1033\fs24   einer Person und schlie\u223 \'dflich vor dem {\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Bischof}}\plain \f1\lang1033\fs24 , wo ihn die ehemalige Geliebte anklagt. Simultane Wiedergabe dreier Episoden in einer Miniatur ist bei dieser Causa selten (s. \plain \f1\scaps\lang1033\fs24 Melnikas\plain \f1\lang1033\fs24 , Bd. 2, S. 488).}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Verdana;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red157\green185\blue235;\red157\green185\blue235;}

