\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  287\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Aufl\u246 \'f6sung einer Verlobung wegen eines Keuschheitsgel\u252 \'fcbdes (\plain \f1\i\lang1033\fs24  Causa XXVII\plain \f1\lang1033\fs24 ). 8 x 8,5 cm. Szene unter zwei Arkadenb\u246 \'f6gen. Rechts steht das jugendliche Paar vor einem weltlichen Gelehrten, der seinen Mantel wie einen Schutzmantel weit um sie breitet und offenbar die {\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Verlobung}}\plain \f1\lang1033\fs24   vollzieht. Im linken Bildteil der klagende Verlobte vor dem thronenden Bischof, nachdem seine Braut einen anderen Mann geheiratet hat, weil sie das Keuschheitsgel\u252 \'fcbde ihres Verlobten nicht akzeptieren wollte.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Verdana;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red157\green185\blue235;\red157\green185\blue235;}

