\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt: \plain \f1\lang1033\fs24  1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   vacat. 2\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 76\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Officium beatae Mariae virginis. 77\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   vacat (Abklatsch von 76\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ). 78\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 122\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Officium reverendissimi crucis. 122\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 124\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacant (124\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24    Abklatsch von 125\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ). 125\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 175\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Officium mortuorum. 175\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 188\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Bu\u223 \'dfpsalmen. 188\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 196\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Litanei. 196\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 216\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Gebete (u.a. 197\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  [\u8230 \'85] Petri buere dignare domine omnibus nobis bona facientibus propter nomen tuum vitam eternam [\u8230 \'85]\plain \f1\lang1033\fs24  ; Petrus Boerius? [gest. 1397]). 217\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 220\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   beigebundenes Fragment (Anfang 14. Jh.): 217\plain \f1\super\lang1033\fs32 r\plain \f1\lang1033\fs24   Gebet zum hl. Bernhard. 217\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 220\plain \f1\super\lang1033\fs24 v \plain \f1\lang1033\fs24  Ablassgebete (u.a. 219\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  [\u8230 \'85] fons pietatis [\u8230 \'85]  pro me pecatrice famula tua [Na..]na [?\u8230 \'85]\plain \f1\lang1033\fs24 )\plain \f1\scaps\lang1033\fs24 . \plain \f1\lang1033\fs24  221\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 222\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacant (221\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Schriftabklatsch von 220\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ). }

