\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5260[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Pergament}}\plain \f1\lang1033\fs24   (Bl. 287a und 297a Papier), {\field{\*\fldinst HYPERLINK "hida://5706[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 300 Bl.}}\plain \f1\lang1033\fs24   (gez\u228 \'e4hlt 298, Doppelz\u228 \'e4hlung 162a/ 162b; zus\u228 \'e4tzlich 287a), {\field{\*\fldinst HYPERLINK "hida://5360[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 43,5 x 26}}\plain \f1\lang1033\fs24   cm (Bl. 287a: 33 x 21 cm). 14 V\plain \f1\super\lang1033\fs24 140\plain \f1\lang1033\fs24   + VI\plain \f1\super\lang1033\fs24 152\plain \f1\lang1033\fs24   + 6 V\plain \f1\super\lang1033\fs24 211\plain \f1\lang1033\fs24   + (IV\endash 1)\plain \f1\super\lang1033\fs24 218\plain \f1\lang1033\fs24   + 4 V\plain \f1\super\lang1033\fs24 258\plain \f1\lang1033\fs24   + II\plain \f1\super\lang1033\fs24 262\plain \f1\lang1033\fs24   + 3 V\plain \f1\super\lang1033\fs24 292\plain \f1\lang1033\fs24   + (IV\endash 2+1)\plain \f1\super\lang1033\fs24 298\plain \f1\lang1033\fs24 . Schriftspiegel: 32,5\endash 33,5 x 18,5\endash 19 cm. 2 Spalten. 83\endash 88 Zeilen. {\field{\*\fldinst HYPERLINK "hida://5704[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Gotische Minuskel}}\plain \f1\lang1033\fs24   von mehreren H\u228 \'e4nden. Zahlreiche rote und blaue Paragraphzeichen. Seitentitel in Rot und Blau (Buchz\u228 \'e4hlung, ab Causa XXXIII fehlerhaft). Bl. 297a\plain \f1\b\lang1033\fs24   \plain \f1\lang1033\fs24  nachtr\u228 \'e4glich eingeklebt, mit Wasserzeichen Traube im Wappenschild, darunter A, dar\u252 \'fcber C Z (sehr \u228 \'e4hnlich {\field{\*\fldinst HYPERLINK "hida://6560[0].6770/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Piccard, Frucht, 1095}}\plain \f1\lang1033\fs24   u. {\field{\*\fldinst HYPERLINK "hida://6560[1].6770/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 1096}}\plain \f1\lang1033\fs24 : Augsburg, um 1610). Hinterer Spiegel abgel\u246 \'f6st (Bl. 298).}

