\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt: \plain \f1\lang1033\fs24  1\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Eberhardus Bethuniensis}}\plain \f1\lang1033\fs24 , Verse (aus {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Graecismus}}\plain \f1\lang1033\fs24   10, V. 174-240; beginnt auf Versoseite). 2\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 51\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Kommentare zu Ovidius, Metamorphosen}}\plain \f1\lang1033\fs24 . 52\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 57\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Ovidius}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 De remedio amoris}}\plain \f1\lang1033\fs24 . 58\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 80\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Horatius}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Liber epistolarum}}\plain \f1\lang1033\fs24 . 80\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacat. 81\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 117\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[3].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Galfredus de Vinosalvo}}\plain \f1\lang1033\fs24 , {\field{\*\fldi